def test_pipeline_is_lazy():
    pulled = []

    def source():
        for i in itertools.count():
            pulled.append(i)
            yield f"ERROR: e{i}" if i % 3 == 0 else f"INFO: i{i}"
    result = errors_pipeline(source(), 2)
    assert pulled == []
    assert list(result) == ["e0", "e3"]
