def worker(name, n):
    for i in range(n):
        yield f"{name}{i}"
    return f"{name} done"


def test_run_all_values_and_return():
    g = run_all(worker("a", 2), worker("b", 1))
    values = []
    try:
        while True:
            values.append(next(g))
    except StopIteration as stop:
        result = stop.value
    assert values == ["a0", "a1", "b0"] and result == ["a done", "b done"]


def test_send_reaches_subgenerator():
