        received = []
        while True:
            x = yield len(received)
            if x is None:
                return received
            received.append(x)
    g = run_all(echo())
    assert next(g) == 0
    assert g.send("x") == 1 and g.send("y") == 2
    try:
        g.send(None)
    except StopIteration as stop:
        assert stop.value == [["x", "y"]]


def test_empty_run_all():
