def flatten(items):
    for x in items:
        if isinstance(x, (list, tuple)):
            yield from flatten(x)
        else:
            yield x


def run_all(*generators):
    results = []
    for g in generators:
        results.append((yield from g))
    return results

class Reset(Exception):
    pass


def averager(log=None):
    total = 0.0
    count = 0
    value = None
    while True:
        try:
            x = yield value
        except Reset:
            total, count, value = 0.0, 0, None
            continue
        except GeneratorExit:
            if log is not None:
                log.append((count, total / count if count else None))
            raise
        total += x
        count += 1
        value = total / count

