def build_index(docs):
    words = {w for text in docs.values() for w in text.lower().split()}
    return {w: {doc_id for doc_id, text in docs.items() if w in text.lower().split()} for w in words}


def transpose(matrix):
    if not matrix:
        return []
    return [[row[c] for row in matrix] for c in range(len(matrix[0]))]


def word_lengths(text):
    return {len(w) for w in text.split() if len(w) >= 3}

