def test_constant_memory():
    tracemalloc.start()
    try:
        tracemalloc.reset_peak()
        assert sum_of_squares(200_000) == sum(i * i for i in range(200_000))
        s = stream_stats(i for i in range(200_000))
        _, peak = tracemalloc.get_traced_memory()
    finally:
        tracemalloc.stop()
    assert s["count"] == 200_000
    assert peak < 200_000, f"peak {peak} bytes suggests a list was built"

