import functools


def count_calls(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return fn(*args, **kwargs)

    def reset_calls():
        wrapper.calls = 0

    wrapper.calls = 0
    wrapper.reset_calls = reset_calls
    return wrapper

