class Typed:
    def __init__(self, expected_type, *, nullable=False):
        self.expected_type = expected_type
        self.nullable = nullable
        self.name = None

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        try:
            return obj.__dict__[self.name]
        except KeyError:
            raise AttributeError(self.name) from None

    def _type_name(self):
        t = self.expected_type
        return " or ".join(x.__name__ for x in t) if isinstance(t, tuple) else t.__name__

    def __set__(self, obj, value):
        if value is None and self.nullable:
            pass
        elif not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name} must be {self._type_name()}, got {type(value).__name__}")
        obj.__dict__[self.name] = value

    def __delete__(self, obj):
        try:
            del obj.__dict__[self.name]
        except KeyError:
            raise AttributeError(self.name) from None

