class Plugin:
    registry = {}

    def __init_subclass__(cls, name=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if name is None:
            return
        if name in Plugin.registry:
            raise ValueError(f"plugin name {name!r} already registered")
        cls.plugin_name = name
        Plugin.registry[name] = cls

    @classmethod
    def create(cls, name, *args, **kwargs):
        return Plugin.registry[name](*args, **kwargs)

class Field:
    def __init__(self, default=None, required=False):
        self.default = default
        self.required = required


class ModelMeta(type):
    def __new__(mcls, name, bases, ns):
        fields = {}
        for base in reversed(bases):
            fields.update(getattr(base, "_fields", {}))
        own = {k: v for k, v in ns.items() if isinstance(v, Field)}
        for k in own:
            del ns[k]
        fields.update(own)
        cls = super().__new__(mcls, name, bases, ns)
        cls._fields = dict(fields)
        return cls


class Model(metaclass=ModelMeta):
    def __init__(self, **kwargs):
        unknown = set(kwargs) - set(self._fields)
        if unknown:
            raise TypeError(f"unknown fields: {sorted(unknown)}")
        for name, f in self._fields.items():
            if name in kwargs:
                value = kwargs[name]
            elif f.required:
                raise TypeError(f"missing required field {name!r}")
            else:
                value = f.default
            setattr(self, name, value)

    def __repr__(self):
        args = ", ".join(f"{n}={getattr(self, n)!r}" for n in self._fields)
        return f"{type(self).__name__}({args})"

    def __eq__(self, other):
        if type(other) is not type(self):
            return NotImplemented
        return all(getattr(self, n) == getattr(other, n) for n in self._fields)

