class Transaction:
    def __init__(self, store):
        self.store = store
        self._work = None

    def __enter__(self):
        self._work = dict(self.store)
        return self._work

    def __exit__(self, exc_type, exc, tb):
        if exc_type is None:
            self.store.clear()
            self.store.update(self._work)
        self._work = None
        return False

