        if self._old is not _MISSING and self.name not in getattr(self.obj, "__dict__", {}):
            self._old = (_MISSING, self._old)
        setattr(self.obj, self.name, self.value)
        return self.obj

    def __exit__(self, *exc):
        if self._old is _MISSING or isinstance(self._old, tuple) and self._old and self._old[0] is _MISSING:
            delattr(self.obj, self.name)
            if isinstance(self._old, tuple) and self._old and self._old[0] is _MISSING:
                if getattr(self.obj, self.name, _MISSING) != self._old[1]:
                    setattr(self.obj, self.name, self._old[1])
        else:
