from contextlib import contextmanager

_MISSING = object()


@contextmanager
def patched(mapping, **overrides):
    saved = {k: mapping.get(k, _MISSING) if k in mapping else _MISSING for k in overrides}
    try:
        for k, v in overrides.items():
            if v is None:
                mapping.pop(k, None)
            else:
                mapping[k] = v
        yield mapping
    finally:
        for k, old in saved.items():
            if old is _MISSING:
                mapping.pop(k, None)
            else:
                mapping[k] = old

