import json


class DictMixin:
    def to_dict(self):
        return {k: self._convert(v) for k, v in vars(self).items() if not k.startswith("_")}

    @classmethod
    def _convert(cls, v):
        if hasattr(v, "to_dict"):
            return v.to_dict()
        if isinstance(v, (list, tuple)):
            return [cls._convert(x) for x in v]
        if isinstance(v, dict):
            return {k: cls._convert(x) for k, x in v.items()}
        return v


class JsonMixin:
    def to_json(self, **kwargs):
        return json.dumps(self.to_dict(), **kwargs)


class ReprMixin:
    def __repr__(self):
        attrs = ", ".join(f"{k}={v!r}" for k, v in sorted(vars(self).items()) if not k.startswith("_"))
        return f"{type(self).__name__}({attrs})"

