import html


def render(obj):
    method = getattr(obj, "__html__", None)
    if callable(method):
        return method()
    if isinstance(obj, str):
        return html.escape(obj)
    items = getattr(obj, "items", None)
    if callable(items):
        return "<dl>" + "".join(f"<dt>{render(k)}</dt><dd>{render(v)}</dd>" for k, v in items()) + "</dl>"
    try:
        it = iter(obj)
    except TypeError:
        return html.escape(str(obj))
    return "<ul>" + "".join(f"<li>{render(x)}</li>" for x in it) + "</ul>"

