from typing import Protocol, runtime_checkable


@runtime_checkable
class Exporter(Protocol):
    name: str

    def export(self, rows: list[dict]) -> str:
        ...


class ExporterRegistry:
    def __init__(self):
        self._by_name = {}

    def register(self, exporter):
        if not isinstance(exporter, Exporter):
            raise TypeError(f"{exporter!r} does not implement Exporter")
        if exporter.name in self._by_name:
            raise ValueError(f"duplicate exporter {exporter.name!r}")
        self._by_name[exporter.name] = exporter
        return exporter

    def get(self, name):
        return self._by_name[name]

    def names(self):
        return sorted(self._by_name)

    def export(self, name, rows):
        return self.get(name).export(rows)


class CsvExporter:
    name = "csv"

    def export(self, rows):
        if not rows:
            return ""
        buf = io.StringIO()
        w = csv.DictWriter(buf, fieldnames=list(rows[0]), lineterminator="\n")
        w.writeheader()
        w.writerows(rows)
        return buf.getvalue()


