import csv
import io
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation


@dataclass
class Order:
    id: str
    customer: str
    amount: Decimal


def parse_orders(csv_text):
    out = []
    for row in csv.DictReader(io.StringIO(csv_text)):
        try:
            amount = Decimal(row["amount"])
        except InvalidOperation:
            raise ValueError(f"bad amount {row['amount']!r}") from None
        out.append(Order(row["id"], row["customer"], amount))
    return out


def validate(order):
    problems = []
    if not order.customer.strip():
        problems.append("empty customer")
    if order.amount <= 0:
        problems.append("non-positive amount")
    return problems


def summarize(orders):
    by_customer = {}
    for o in orders:
        by_customer[o.customer] = by_customer.get(o.customer, Decimal("0")) + o.amount
    return {"count": len(orders), "total": sum((o.amount for o in orders), Decimal("0")), "by_customer": by_customer}


def format_report(summary):
    lines = [f"Orders: {summary['count']}", f"Total: {summary['total']:.2f}"]
    for name in sorted(summary["by_customer"]):
        lines.append(f"  {name}: {summary['by_customer'][name]:.2f}")
    return "\n".join(lines)


def generate_report(csv_text):
    orders = [o for o in parse_orders(csv_text) if not validate(o)]
    return format_report(summarize(orders))

