class FixedOff:
    def __init__(self, amount, code=None):
        self.amount = Decimal(str(amount))
        self.code = code

    def apply(self, price, order):
        if self.code is None or order.get("coupon") == self.code:
            return price - self.amount
        return price


class MinimumPrice:
    def __init__(self, floor):
        self.floor = Decimal(str(floor))

    def apply(self, price, order):
        return max(price, self.floor)


class PriceCalculator:
    def __init__(self, rules):
        self.rules = list(rules)

    def total(self, base_price, order=None):
        order = order or {}
        price = Decimal(str(base_price))
        for rule in self.rules:
            price = max(Decimal("0"), rule.apply(price, order))
        return price.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

