        self.mailer = mailer
        self.clock = clock
        self.failed_emails = []

    def signup(self, email):
        email = email.strip().lower()
        if "@" not in email:
            raise ValueError(f"invalid email {email!r}")
        if self.repo.get(email) is not None:
            raise DuplicateUser(email)
