import math

_REGISTRY = {}


def register_shape(kind):
    def deco(cls):
        if kind in _REGISTRY:
            raise ValueError(f"shape kind {kind!r} already registered")
        _REGISTRY[kind] = cls
        return cls
    return deco


def create_shape(spec):
    params = dict(spec)
    kind = params.pop("kind", None)
    if kind not in _REGISTRY:
        raise ValueError(f"unknown shape kind {kind!r}; known kinds: {', '.join(sorted(_REGISTRY))}")
    try:
        return _REGISTRY[kind](**params)
    except TypeError as exc:
        raise ValueError(f"bad parameters for {kind}: {exc}") from exc


@register_shape("circle")
class Circle:
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2


@register_shape("rect")
class Rect:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

