class Subject:
    def __init__(self):
        self._subs = []

    def subscribe(self, callback):
        token = [callback]
        self._subs.append(token)

        def unsubscribe():
            try:
                self._subs.remove(token)
            except ValueError:
                pass
        return unsubscribe

    def notify(self, *args, **kwargs):
        errors = []
        for token in list(self._subs):
            try:
                token[0](*args, **kwargs)
            except Exception as exc:
                errors.append(exc)
        return errors

