        self.name = name
        self.key = f"_observable_{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.__dict__.get(self.key, self.default)

    def __set__(self, obj, value):
        old = self.__get__(obj)
        obj.__dict__[self.key] = value
        if old != value and isinstance(obj, Observable):
            obj._fire(self.name, old, value)


class Observable:
    def on_change(self, attr_name, callback):
        listeners = self.__dict__.setdefault("_listeners", {})
        listeners.setdefault(attr_name, []).append(callback)

    def _fire(self, name, old, new):
        listeners = self.__dict__.get("_listeners", {})
        for cb in list(listeners.get(name, [])):
            cb(self, old, new)
        for cb in list(listeners.get("*", [])):
            cb(self, name, old, new)

