_STRATEGIES = {}


def register_strategy(name):
    def deco(fn):
        _STRATEGIES[name] = fn
        return fn
    return deco


@register_strategy("by_name")
def _by_name(r):
    return r["name"].lower()


@register_strategy("by_age_desc")
def _by_age_desc(r):
    return (-r["age"], r["name"])


@register_strategy("by_created")
def _by_created(r):
    return r["created"]


def sort_records(records, strategy):
    if isinstance(strategy, str):
        try:
            key = _STRATEGIES[strategy]
        except KeyError:
            raise ValueError(f"unknown strategy {strategy!r}") from None
    elif hasattr(strategy, "key") and callable(strategy.key):
        key = strategy.key
    elif callable(strategy):
        key = strategy
    else:
        raise TypeError("strategy must be a name, a key function or an object with key()")
    return sorted(records, key=key)

