class Insert:
    def __init__(self, pos, s):
        self.pos, self.s = pos, s

    def execute(self, doc):
        if not 0 <= self.pos <= len(doc.text):
            raise IndexError("position out of range")
        doc.text = doc.text[:self.pos] + self.s + doc.text[self.pos:]

    def undo(self, doc):
