class CheckoutError(Exception):
    pass


class CheckoutFacade:
    def __init__(self, inventory, payments, shipping):
        self.inventory = inventory
        self.payments = payments
        self.shipping = shipping

    def place_order(self, order_id, items, prices, card):
        total = sum((Decimal(prices[sku]) * qty for sku, qty in items.items()), Decimal("0"))
        try:
            reservation = self.inventory.reserve(order_id, items)
        except Exception as exc:
            raise CheckoutError(f"could not reserve stock for {order_id}") from exc
        try:
            charge = self.payments.charge(order_id, total, card)
        except Exception as exc:
            self.inventory.release(reservation)
            raise CheckoutError(f"payment failed for {order_id}") from exc
        try:
            return self.shipping.create_shipment(order_id, items)
        except Exception as exc:
            self.payments.refund(charge)
            self.inventory.release(reservation)
            raise CheckoutError(f"shipping failed for {order_id}") from exc

