        self._state = "new"
        self.history = []

    @property
    def state(self):
        return self._state

    def _do(self, action):
        nxt = _TRANSITIONS.get((self._state, action))
        if nxt is None:
            raise InvalidTransition(self._state, action)
        self.history.append((self._state, nxt))
        self._state = nxt

    def pay(self):
