import abc


class ReportExporter(abc.ABC):
    def export(self, columns, rows):
        parts = []
        head = self.header(columns)
        if head is not None:
            parts.append(head)
        parts.extend(self.format_row(r) for r in rows)
        foot = self.footer(len(rows))
        if foot is not None:
            parts.append(foot)
        return "\n".join(parts)

    def header(self, columns):
        return None

    @abc.abstractmethod
    def format_row(self, row):
        ...

    def footer(self, count):
        return None


class CsvReport(ReportExporter):
    def header(self, columns):
        return ",".join(map(str, columns))

    def format_row(self, row):
        return ",".join(map(str, row))


class MarkdownReport(ReportExporter):
    def header(self, columns):
        return "| " + " | ".join(map(str, columns)) + " |\n" + "| " + " | ".join("---" for _ in columns) + " |"

    def format_row(self, row):
        return "| " + " | ".join(map(str, row)) + " |"

    def footer(self, count):
        return f"_{count} rows_"

