import abc
import sqlite3
from dataclasses import dataclass, replace
from typing import Optional


@dataclass
class User:
    name: str
    email: str
    id: Optional[int] = None


class UserRepository(abc.ABC):
    @abc.abstractmethod
    def add(self, user):
        ...

    @abc.abstractmethod
    def get(self, user_id):
        ...

    @abc.abstractmethod
    def find_by_email(self, email):
        ...

    @abc.abstractmethod
    def list(self):
        ...


class InMemoryUserRepository(UserRepository):
    def __init__(self):
        self._users = {}
        self._next = 1

    def add(self, user):
        if self.find_by_email(user.email) is not None:
            raise ValueError(f"duplicate email {user.email}")
        uid = user.id if user.id is not None else self._next
        self._next = max(self._next, uid + 1)
        stored = replace(user, id=uid)
        self._users[uid] = stored
        return replace(stored)

    def get(self, user_id):
        u = self._users.get(user_id)
        return replace(u) if u else None

    def find_by_email(self, email):
        for u in self._users.values():
            if u.email.lower() == email.lower():
                return replace(u)
        return None

    def list(self):
        return [replace(self._users[k]) for k in sorted(self._users)]


class SqliteUserRepository(UserRepository):
    def __init__(self, conn):
        self.conn = conn
        conn.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, "
                     "email TEXT NOT NULL, email_key TEXT NOT NULL UNIQUE)")

    @staticmethod
    def _row(r):
        return User(r[1], r[2], r[0]) if r else None

    def add(self, user):
        try:
            with self.conn:
                cur = self.conn.execute("INSERT INTO users (id, name, email, email_key) VALUES (?, ?, ?, ?)",
                                        (user.id, user.name, user.email, user.email.lower()))
        except sqlite3.IntegrityError:
            raise ValueError(f"duplicate email {user.email}") from None
        return self.get(cur.lastrowid if user.id is None else user.id)

    def get(self, user_id):
        return self._row(self.conn.execute("SELECT id, name, email FROM users WHERE id = ?", (user_id,)).fetchone())

    def find_by_email(self, email):
        return self._row(self.conn.execute("SELECT id, name, email FROM users WHERE email_key = ?",
                                           (email.lower(),)).fetchone())

    def list(self):
        return [self._row(r) for r in self.conn.execute("SELECT id, name, email FROM users ORDER BY id")]

