import re

_HEX = re.compile(r"#?([0-9a-fA-F]{3}|[0-9a-fA-F]{6})")
_RGB = re.compile(r"\s*rgb\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)\s*")


class Color:
    def __init__(self, r, g, b):
        for c in (r, g, b):
            if not isinstance(c, int) or isinstance(c, bool) or not 0 <= c <= 255:
                raise ValueError(f"channel out of range: {c!r}")
        self.r, self.g, self.b = r, g, b

    @classmethod
    def from_hex(cls, text):
        m = _HEX.fullmatch(text.strip()) if isinstance(text, str) else None
        if not m:
            raise ValueError(f"not a hex colour: {text!r}")
        digits = m.group(1)
        if len(digits) == 3:
            digits = "".join(ch * 2 for ch in digits)
        return cls(*(int(digits[i:i + 2], 16) for i in (0, 2, 4)))

    @classmethod
    def from_rgb_string(cls, text):
        m = _RGB.fullmatch(text)
        if not m:
            raise ValueError(f"not an rgb() string: {text!r}")
        return cls(*(int(x) for x in m.groups()))

    def to_hex(self):
        return f"#{self.r:02x}{self.g:02x}{self.b:02x}"

    def __eq__(self, other):
        if not isinstance(other, Color):
            return NotImplemented
        return (self.r, self.g, self.b) == (other.r, other.g, other.b)

    def __hash__(self):
        return hash((self.r, self.g, self.b))

    def __repr__(self):
        return f"{type(self).__name__}({self.r}, {self.g}, {self.b})"

