class PaymentError(Exception):
    retryable = False


class CardDeclined(PaymentError):
    def __init__(self, code):
        super().__init__(f"card declined: {code}")
        self.code = code


class InsufficientFunds(CardDeclined):
    def __init__(self, needed):
        super().__init__("insufficient_funds")
        self.needed = needed


class GatewayError(PaymentError):
    retryable = True

    def __init__(self, status):
        super().__init__(f"gateway error (HTTP {status})")
        self.status = status


class GatewayTimeout(GatewayError):
    def __init__(self):
        super().__init__(504)
        self.args = ("gateway timed out",)


def charge(response):
    status = response.get("status")
    if status == "ok":
        return response["id"]
    if status == "declined":
        if response.get("code") == "insufficient_funds":
            raise InsufficientFunds(response["needed"])
        raise CardDeclined(response.get("code"))
    if status == "error":
        raise GatewayError(response.get("http"))
    if status == "timeout":
        raise GatewayTimeout()
    raise PaymentError(f"unexpected gateway response: {response!r}")

class ConfigError(Exception):
    pass


class MissingKey(ConfigError, KeyError):
    def __init__(self, key):
        super().__init__(key)
        self.key = key

    def __str__(self):
        return f"missing required key '{self.key}'"


class InvalidValue(ConfigError, ValueError):
    def __init__(self, key, value, reason):
        super().__init__(key, value, reason)
        self.key, self.value, self.reason = key, value, reason

    def __str__(self):
        return f"invalid value for '{self.key}': {self.value!r} ({self.reason})"


def get_int(config, key, *, min=None, max=None):
    if key not in config:
        raise MissingKey(key)
    raw = config[key]
    if isinstance(raw, bool):
        raise InvalidValue(key, raw, "not an integer")
    if isinstance(raw, int):
        value = raw
    elif isinstance(raw, str) and raw.strip().lstrip("-").isdigit():
        value = int(raw)
    else:
        raise InvalidValue(key, raw, "not an integer")
    if min is not None and value < min:
        raise InvalidValue(key, raw, f"below minimum {min}")
    if max is not None and value > max:
        raise InvalidValue(key, raw, f"above maximum {max}")
    return value

