class Err:
    error: Any

    def is_ok(self):
        return False

    def map(self, fn):
        return self

    def unwrap(self):
        if isinstance(self.error, BaseException):
            raise self.error
        raise ValueError(self.error)

    def unwrap_or(self, default):
