class Registry:
    def __init__(self):
        self._lock = threading.RLock()
        self._items = {}

    def register(self, name, value):
        with self._lock:
            if name in self._items:
                raise KeyError(f"{name!r} already registered")
            self._items[name] = value

    def register_many(self, items):
        with self._lock:
            clash = [n for n in items if n in self._items]
            if clash:
                raise KeyError(f"already registered: {clash}")
            for name, value in items.items():
                self.register(name, value)

    def get(self, name):
        with self._lock:
            return self._items[name]

    def snapshot(self):
        with self._lock:
            return dict(self._items)

    def __len__(self):
        with self._lock:
            return len(self._items)

