import concurrent.futures as cf


class AllFailed(Exception):
    def __init__(self, errors):
        super().__init__(f"all {len(errors)} calls failed")
        self.errors = errors


def first_successful(callables, timeout=None):
    callables = list(callables)
    if not callables:
        raise ValueError("no callables")
    ex = cf.ThreadPoolExecutor(max_workers=len(callables))
    try:
        futs = [ex.submit(c) for c in callables]
        try:
            for fut in cf.as_completed(futs, timeout=timeout):
                if fut.exception() is None:
                    return fut.result()
        except cf.TimeoutError:
            raise TimeoutError("no call succeeded in time") from None
        raise AllFailed([f.exception() for f in futs])
    finally:
        ex.shutdown(wait=False, cancel_futures=True)

