                        rec = json.loads(line)
                    except ValueError:
                        break
                    self._apply(rec)
        self._wal = open(self._wal_path, "a")

    def _apply(self, rec):
        if rec["op"] == "set":
            self._data[rec["k"]] = rec["v"]
        else:
            self._data.pop(rec["k"], None)

    def _log(self, rec):
        self._wal.write(json.dumps(rec) + "\n")
        self._wal.flush()
        self._apply(rec)

    def set(self, key, value):
        self._log({"op": "set", "k": key, "v": value})

    def delete(self, key):
        self._log({"op": "del", "k": key})

    def get(self, key, default=None):
        return self._data.get(key, default)

    def items(self):
        return sorted(self._data.items())

    def checkpoint(self):
        tmp = self._snap_path + ".tmp"
        with open(tmp, "w") as f:
            json.dump(self._data, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, self._snap_path)
        self._wal.close()
        self._wal = open(self._wal_path, "w")

    def close(self):
        self._wal.close()

