@dataclass(frozen=True)
class Opened:
    account_id: str
    owner: str


@dataclass(frozen=True)
class Deposited:
    amount: int


@dataclass(frozen=True)
class Withdrawn:
    amount: int


@dataclass(frozen=True)
class Closed:
    pass


class Account:
    def __init__(self):
        self.id = None
        self.owner = None
        self.balance = 0
        self.closed = False
        self.version = 0
        self.pending_events = []

    @classmethod
    def open(cls, account_id, owner):
        acc = cls()
        acc._record(Opened(account_id, owner))
        return acc

    @classmethod
    def from_events(cls, events):
        acc = cls()
        for e in events:
            acc._apply(e)
        return acc

    def _apply(self, e):
        if isinstance(e, Opened):
            self.id, self.owner = e.account_id, e.owner
        elif isinstance(e, Deposited):
            self.balance += e.amount
        elif isinstance(e, Withdrawn):
            self.balance -= e.amount
        elif isinstance(e, Closed):
            self.closed = True
        else:
            raise DomainError(f"unknown event {e!r}")
        self.version += 1

    def _record(self, e):
        self._apply(e)
        self.pending_events.append(e)

    def _check_open(self):
        if self.closed:
            raise DomainError("account is closed")

    @staticmethod
    def _check_amount(amount):
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            raise DomainError("amount must be a positive int")

    def deposit(self, amount):
        self._check_open()
        self._check_amount(amount)
        self._record(Deposited(amount))

    def withdraw(self, amount):
        self._check_open()
        self._check_amount(amount)
        if amount > self.balance:
            raise DomainError("insufficient funds")
        self._record(Withdrawn(amount))

    def close(self):
        self._check_open()
        if self.balance != 0:
            raise DomainError("balance must be zero to close")
        self._record(Closed())

