    return out


class LayeredConfig:
    def __init__(self, *layers):
        self.layers = list(layers)

    def _values(self, key):
        parts = key.split(".")
        return [(name, v) for name, m in self.layers if (v := _lookup(m, parts)) is not _MISSING]

    def get(self, key, default=_MISSING):
        vals = self._values(key)
        if not vals:
            if default is _MISSING:
                raise KeyError(key)
            return default
        top = vals[0][1]
        if not isinstance(top, dict):
            return top
        result = {}
        for _, v in reversed(vals):
            result = _merge(result, v) if isinstance(v, dict) else {}
        return result

    def source(self, key):
        vals = self._values(key)
        if not vals:
            raise KeyError(key)
        return vals[0][0]

    def as_dict(self):
        result = {}
        for _, m in reversed(self.layers):
            result = _merge(result, m)
        return result

