            raise ValueError("bad capacity or error rate")
        self.capacity = capacity
        self.error_rate = error_rate
        self.size_bits = math.ceil(-capacity * math.log(error_rate) / math.log(2) ** 2)
        self.num_hashes = max(1, round(self.size_bits / capacity * math.log(2)))
        self._bits = bytearray((self.size_bits + 7) // 8)
        self._count = 0

    def _positions(self, item):
        if isinstance(item, str):
            item = item.encode()
        d = hashlib.sha256(item).digest()
        h1 = int.from_bytes(d[:8], "big")
        h2 = int.from_bytes(d[8:16], "big")
        return [(h1 + i * h2) % self.size_bits for i in range(self.num_hashes)]

    def add(self, item):
        for p in self._positions(item):
            self._bits[p >> 3] |= 1 << (p & 7)
        self._count += 1

    def __contains__(self, item):
        return all(self._bits[p >> 3] & (1 << (p & 7)) for p in self._positions(item))

    def __len__(self):
        return self._count

    def union(self, other):
        if (self.size_bits, self.num_hashes) != (other.size_bits, other.num_hashes):
            raise ValueError("incompatible filters")
        out = BloomFilter(self.capacity, self.error_rate)
        out._bits = bytearray(a | b for a, b in zip(self._bits, other._bits))
        out._count = self._count + other._count
        return out

class Autocomplete:
    def __init__(self):
        self._root = {}
        self._count = 0

    def add(self, word, weight=1):
        node = self._root
        for ch in word.lower():
            node = node.setdefault(ch, {})
        if "$" not in node:
            node["$"] = 0
            self._count += 1
        node["$"] += weight

    def _find(self, prefix):
        node = self._root
        for ch in prefix:
            node = node.get(ch)
            if node is None:
                return None
        return node

    def suggest(self, prefix, limit=5):
        prefix = prefix.lower()
        node = self._find(prefix)
        if node is None:
            return []
        found = []
        stack = [(node, prefix)]
        while stack:
            n, path = stack.pop()
            for ch, child in n.items():
                if ch == "$":
                    found.append((-child, path))
                else:
                    stack.append((child, path + ch))
        found.sort()
        return [w for _, w in found[:limit]]

    def remove(self, word):
        word = word.lower()
        path = [self._root]
        for ch in word:
            nxt = path[-1].get(ch)
            if nxt is None:
                return False
            path.append(nxt)
        if "$" not in path[-1]:
            return False
        del path[-1]["$"]
        self._count -= 1
        for i in range(len(word), 0, -1):
            if path[i]:
                break
            del path[i - 1][word[i - 1]]
        return True

    def __contains__(self, word):
        node = self._find(word.lower())
        return node is not None and "$" in node

    def __len__(self):
        return self._count

class _Node:
    __slots__ = ("children", "count", "end")

    def __init__(self):
        self.children = {}
        self.count = 0
        self.end = False


class Trie:
    def __init__(self):
        self._root = _Node()

    def _walk(self, s):
        node = self._root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def contains(self, word):
        n = self._walk(word)
        return n is not None and n.end

    def insert(self, word):
        if self.contains(word):
            return
        node = self._root
        node.count += 1
        for ch in word:
            node = node.children.setdefault(ch, _Node())
            node.count += 1
        node.end = True

    def delete(self, word):
        if not self.contains(word):
            return False
        node = self._root
        node.count -= 1
        for ch in word:
            child = node.children[ch]
            child.count -= 1
            if child.count == 0:
                del node.children[ch]
                return True
            node = child
        node.end = False
        return True

    def count_prefix(self, prefix):
        n = self._walk(prefix)
        return 0 if n is None else n.count

    def longest_common_prefix(self):
        node, out = self._root, []
        if node.count == 0:
            return ""
        while len(node.children) == 1 and not node.end:
            ch, node = next(iter(node.children.items()))
            out.append(ch)
        return "".join(out)

from collections import defaultdict


class OutOfStock(Exception):
    def __init__(self, sku, requested, available):
        super().__init__(f"{sku}: requested {requested}, available {available}")
        self.sku = sku


def _check_qty(qty):
    if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
        raise ValueError(f"quantity must be a positive int, got {qty!r}")


class Inventory:
    def __init__(self):
        self._on_hand = defaultdict(int)
        self._reserved = defaultdict(int)
        self._orders = {}

    def add_stock(self, sku, qty):
        _check_qty(qty)
        self._on_hand[sku] += qty

    def on_hand(self, sku):
        return self._on_hand.get(sku, 0)

    def available(self, sku):
        return self._on_hand.get(sku, 0) - self._reserved.get(sku, 0)

    def reserve(self, order_id, items):
        if order_id in self._orders:
            raise ValueError(f"order {order_id!r} already has a reservation")
        for qty in items.values():
            _check_qty(qty)
        for sku, qty in items.items():
            if self.available(sku) < qty:
                raise OutOfStock(sku, qty, self.available(sku))
        for sku, qty in items.items():
            self._reserved[sku] += qty
        self._orders[order_id] = dict(items)

    def release(self, order_id):
        for sku, qty in self._orders.pop(order_id).items():
            self._reserved[sku] -= qty

    def commit(self, order_id):
        for sku, qty in self._orders.pop(order_id).items():
            self._reserved[sku] -= qty
            self._on_hand[sku] -= qty

    def check_invariants(self):
        for sku in set(self._on_hand) | set(self._reserved):
            assert self._on_hand[sku] >= 0, sku
            assert 0 <= self._reserved[sku] <= self._on_hand[sku], sku

from decimal import Decimal


class LedgerError(Exception):
    pass


def _amount(x):
    if isinstance(x, float):
        raise TypeError("use Decimal, int or str for money, not float")
    if isinstance(x, bool) or not isinstance(x, (int, str, Decimal)):
        raise TypeError(f"bad amount type {type(x).__name__}")
    return Decimal(x)


class Ledger:
    def __init__(self):
        self._bal = {}
        self._neg = {}
        self._hist = {}

    def open(self, name, allow_negative=False):
        if name in self._bal:
            raise LedgerError(f"account {name!r} exists")
        self._bal[name] = Decimal(0)
        self._neg[name] = allow_negative
        self._hist[name] = []

    def post(self, entries, memo=""):
        legs = [(acct, _amount(amt)) for acct, amt in entries]
        if not legs:
            raise LedgerError("no legs")
        if sum(a for _, a in legs) != 0:
            raise LedgerError("legs do not balance")
        new = {}
        for acct, amt in legs:
            if acct not in self._bal:
                raise LedgerError(f"unknown account {acct!r}")
            new[acct] = new.get(acct, self._bal[acct]) + amt
        for acct, bal in new.items():
            if bal < 0 and not self._neg[acct]:
                raise LedgerError(f"{acct} would go negative")
        self._bal.update(new)
        for acct, amt in legs:
            self._hist[acct].append((memo, amt))

    def balance(self, name):
        return self._bal[name]

    def history(self, name):
        return list(self._hist[name])

    def total(self):
        return sum(self._bal.values(), Decimal(0))

