class _Call:
    def __init__(self):
        self.done = threading.Event()
        self.result = None
        self.error = None
        self.callers = 1


class SingleFlight:
    def __init__(self):
        self._lock = threading.Lock()
        self._calls = {}

    def inflight(self, key):
        with self._lock:
            c = self._calls.get(key)
            return c.callers if c else 0

    def do(self, key, fn):
        with self._lock:
            call = self._calls.get(key)
            if call is not None:
                call.callers += 1
                leader = False
            else:
                call = self._calls[key] = _Call()
                leader = True
        if leader:
            try:
                call.result = fn()
            except BaseException as exc:
                call.error = exc
            finally:
                with self._lock:
                    del self._calls[key]
                call.done.set()
        else:
            call.done.wait()
        if call.error is not None:
            raise call.error
        return call.result

