import time


class IdempotencyConflict(Exception):
    pass


def _fingerprint(payload):
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()


class IdempotencyStore:
    def __init__(self, ttl: float = 86400, clock=time.monotonic):
        self.ttl = ttl
        self.clock = clock
        self._entries = {}

    def _get(self, key):
        e = self._entries.get(key)
        if e is not None and self.clock() >= e[2]:
            del self._entries[key]
            return None
        return e

    def handle(self, key, payload, fn):
        fp = _fingerprint(payload)
        e = self._get(key)
        if e is not None:
            if e[0] != fp:
                raise IdempotencyConflict(f"key {key!r} reused with a different payload")
            return e[1]
        response = fn(payload)
        self._entries[key] = (fp, response, self.clock() + self.ttl)
        return response

    def __len__(self):
        now = self.clock()
        return sum(1 for e in self._entries.values() if now < e[2])

import threading


class RequestInProgress(Exception):
    pass


_RUNNING = object()


class IdempotentHandler:
    def __init__(self, fn):
        self.fn = fn
        self._lock = threading.Lock()
        self._state = {}

    def call(self, key, payload):
        with self._lock:
            st = self._state.get(key)
            if st is _RUNNING:
                raise RequestInProgress(key)
            if st is not None:
                return st[0]
            self._state[key] = _RUNNING
        try:
            result = self.fn(payload)
        except BaseException:
            with self._lock:
                del self._state[key]
            raise
        with self._lock:
            self._state[key] = (result,)
        return result

